package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaPlDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku i Sujood)", "(Allah jest) Najbardziej Uwielbiony, Najświętszy, Pan aniołów i Ducha (Jibril).", "W ruku i sujood.", "Prorok ﷺ recytował to w ruku i sujood."),
        "dua_sujood_dhanbi_kullah" to DuaText("W Sujood: Wybacz wszystkie moje grzechy", "O Allahu, przebacz mi wszystkie moje grzechy – małe i duże, pierwsze i ostatnie, jawne i ukryte.", "W sujud.", "Pokłony to miejsce, w którym znajdują się odpowiedzi na dua."),
        "dua_sujood_ridaka" to DuaText("Schronienie w Twojej przyjemności", "O Allah, szukam schronienia w Twoim upodobaniu przed Twoim gniewem, w Twoim przebaczeniu przed Twoją karą i przed Tobą szukam schronienia u Ciebie. Nie mogę Cię w pełni chwalić; Jesteś taki, jakim siebie chwaliłeś.", "W sujud — Aisha (RA) usłyszała, jak Prorok ﷺ to powiedział.", "Sujud dua Proroka ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Wszystkie werbalne, fizyczne i finansowe akty kultu są dla Allaha. Pokój z tobą, Proroku, i miłosierdzie Allaha i Jego błogosławieństwo. Pokój niech będzie z nami i sprawiedliwymi sługami Allaha. Świadczę, że nikt nie ma prawa być czczonym poza Allahem i zaświadczam, że Muhammad ﷺ jest Jego sługą i Wysłannikiem.", "Na każdym posiedzeniu — opowiadane przez Abdullaha ibn Mas'uda (RA) (praktyka Hanafi).", "Prorok ﷺ nauczał tego jak sura Koranu."),
        "dua_sajdah_tilawah" to DuaText("Sajdah recytacji", "Moje oblicze oddało pokłon temu, który je stworzył i dał mu słuch i wzrok swoją mocą i mocą.", "W pokłonie recytacji.", "Prorok ﷺ powiedział to podczas nocnej recytacji."),
        "dua_after_witr" to DuaText("Po Witrze", "Chwała Królowi Najświętszemu.", "Trzy razy po salamie witr, podnosząc głos po raz trzeci.", "Prorok ﷺ powiedział to po witr."),
        "dua_tahajjud_nur" to DuaText("Błaganie otwierające Tahajjud", "O Allah, Tobie należy się chwała; Ty jesteś Podtrzymującym niebiosa, ziemię i wszystko, co jest w nich. Tobie należy się chwała; Jesteś Światłością niebios, ziemi i wszystkiego, co jest w nich. Tobie należy się chwała; Ty jesteś Prawdą, Twoja obietnica jest prawdziwa, spotkanie z Tobą jest prawdą, Twoje słowo jest prawdą, Raj jest prawdą, Piekło jest prawdą, Prorocy są prawdą, Mahomet ﷺ jest prawdą i Godzina jest prawdą.", "Rozpoczynając nocną modlitwę (tahajjud) (część otwierająca dua).", "Prorok ﷺ wyrecytował to wstając do tahajjud (cały dua znajduje się w al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Prowadź mnie w sprawach spornych", "O Allah, Panie Jibril, Mika'il i Israfil, Stwórca niebios i ziemi, znający to, co niewidzialne i widzialne! Będziesz rozstrzygał między swoimi sługami w tym, w czym się różnili. Prowadź mnie, za Twoim pozwoleniem, do prawdy w tym, w czym się różniliśmy. Zaiste, prowadzisz, kogo chcesz, ku prostej ścieżce.", "Na początku tahajjud – o wskazówki do prawdy pośród nieporozumień.", "Od tego duetu Prorok ﷺ rozpoczął swoją nocną modlitwę."),
        "dua_going_to_mosque_nur" to DuaText("Idąc do meczetu (Dua Światła)", "O Allahu, umieść światło w moim sercu, światło w moich oczach, światło w moich uszach, światło po mojej prawej stronie, światło po mojej lewej stronie, światło nade mną, światło pode mną, światło przede mną, światło za mną i rozjaśnij mnie.", "Idąc do meczetu na Fajr.", "Prorok ﷺ recytował to, wychodząc na modlitwę."),
        "dua_waswasa_salah" to DuaText("Waswasa podczas Salah (Khinzab)", "Szukam schronienia u Allaha przed Szaytanem, przeklętym.", "Kiedy podczas modlitwy usłyszysz szatańskie szepty, poszukaj schronienia i trzykrotnie splunij lekko w lewo.", "Uthman ibn Abil – „Jak (RA) to zrobił i szepty ucichły."),
        "dua_alimal_ghayb" to DuaText("Znawca tego, co skryte", "O Allah, znający to, co skryte i widzialne, Stworzyciel niebios i ziemi, Pan i Władca wszystkich rzeczy! Świadczę, że nie ma boga oprócz Ciebie. Szukam schronienia u Ciebie przed złem, które noszę w sobie, oraz przed złem Szaytana i jego (wezwaniem do) uchylania się.", "Rano, wieczorem i przed snem – Prorok ﷺ nauczył tego Abu Bakr (RA).", "Ochrona przed złem własnym i Szaytana."),
        "dua_fitratil_islam" to DuaText("O Fitrze islamu", "Weszliśmy w poranek fitry islamu, słowa szczerości, religii naszego Proroka Mahometa ﷺ i drogi naszego ojca Ibrahima (AS), który był uczciwy i muzułmaninem i nie należał do politeistów.", "Rano.", "Odnawianie wiary każdego ranka."),
        "dua_amsayna_fitrah" to DuaText("Wieczór poświęcony Fitrze islamu", "Weszliśmy w wieczór w fitrę islamu, w słowa szczerości, w religię naszego proroka Mahometa ﷺ i w drogę naszego ojca Ibrahima (AS), który był prawym i muzułmaninem i nie należał do politeistów.", "Wieczorem.", "Odnawianie wiary każdego wieczoru."),
        "dua_tahleel_10_fajr" to DuaText("Dziesięć Tahleel po Fajr i Maghrib", "Nikt nie jest godny czci poza Allahem, Jedynym, który nie ma żadnego współtowarzysza. Do niego należy panowanie i do niego należy chwała; On daje życie i powoduje śmierć. On jest nad każdą rzeczą wszechwładny.", "Dziesięć razy po Fajr (i Maghrib), zanim wstaniesz z siedzenia lub zaczniesz mówić.", "Dziesięć dobrych uczynków, dziesięć grzechów wymazanych, dziesięć awansów i ochrona przed Szaytanem przez cały dzień."),
        "dua_la_hawla_kanz" to DuaText("Skarb Jannah", "Nie ma mocy ani mocy, jak tylko u Allaha.", "Często, zawsze.", "To jeden ze skarbów Raju."),
        "dua_four_beloved_words" to DuaText("Cztery najbardziej ukochane słowa", "Chwała niech będzie Allahowi, wszelka chwała jest dla Allaha, nikt nie ma prawa być czczonym oprócz Allaha, a Allah jest Największy.", "Słowa najbardziej umiłowane Allahowi.", "Są one droższe Prorokowi ﷺ niż wszystko, nad czym wschodzi słońce."),
        "dua_two_light_words" to DuaText("Dwa słowa zapalają się na języku", "Chwała Bogu i wszelka chwała należy do Niego; chwała Allahowi, Wspaniałemu.", "Lekkie na języku, ciężkie na skali.", "Ukochany Miłosiernemu, lekki na języku i ciężki na Wadze. (Ostatni hadis al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "O Posiadaczu Majestatu i Honoru!", "Trzymaj się tego in dua – ﷺ instrukcji Proroka.", "Prorok ﷺ powiedział: trzymaj się „Ya Dhal-Jalali wal-Ikram”."),
        "dua_sleep_wadatu_janbi" to DuaText("W Twoje Imię Kładę się", "W imię Twoje, Panie mój, kładę bok i w imię Twoje powstaję. Jeśli zabierzesz moją duszę, zmiłuj się nad nią, a jeśli ją uwolnisz, chroń ją, tak jak chronisz Swoje sprawiedliwe sługi.", "Po odkurzeniu łóżka i położeniu się.", "Zawierzenie duszy Allahowi przed snem."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Stworzyłeś moją duszę", "O Allahu, stworzyłeś moją duszę i zabierzesz ją. Jego śmierć i życie należą do Ciebie. Jeśli utrzymasz je przy życiu, chroń je, a jeśli sprawisz, że umrze, przebacz mu. O Allahu, proszę Cię o pomyślność.", "Przed snem — opowiadane przez Ibn Umara (RA).", "Prorok ﷺ poinstruował, aby mówić to przed snem."),
        "dua_sleep_atamana" to DuaText("Wdzięczność przed snem", "Wszelka chwała należy się Allahowi, który nas nakarmił, dał nam pić, wystarczył nam i dał nam schronienie. Ilu jest takich, którzy nie mają nikogo, kto by im wystarczył i dał schronienie.", "Kiedy kładę się do łóżka.", "Prorok ﷺ powiedział to, gdy kładł się do łóżka."),
        "dua_sleep_rabbas_samawat" to DuaText("Panie Niebios — spłać nasz dług", "O Allahu, Panie niebios, ziemi i Potężnego Tronu, nasz Panie i Pan wszystkich rzeczy, Rozdzielacz nasienia i kamienia daktylowego, Objawiciel Tory, Injil i Furqan! U Ciebie szukam schronienia przed złem wszystkiego, czego trzymasz za grzywę. O Allahu, Ty jesteś Pierwszy, nie ma nic przed Tobą; Ty jesteś Ostatni, po Tobie nie ma nic; Ty jesteś Manifestem, nie ma nic ponad Tobą; Jesteś Ukryty, nic nie jest przed Tobą ukryte. Ureguluj za nas nasz dług i uwolnij nas od biedy.", "Przed snem, leżąc na prawym boku — nauczyła Fatimę (RA).", "Duet pozwalający uwolnić się od długów i trudności."),
        "dua_sleep_fear" to DuaText("Strach lub niepokój podczas snu", "W doskonałych słowach Allaha szukam schronienia przed Jego gniewem i karą, przed złem Jego sług, przed podszeptami diabłów i przed ich przyjściem do mnie.", "Kiedy odczuwasz strach lub niepokój podczas snu.", "Jeśli to zrobi, ta rzecz nie zrobi mu krzywdy."),
        "dua_waking_afani" to DuaText("Przebudzenie: przywrócił moją duszę", "Wszelka chwała należy się Allahowi, który zapewnił zdrowie mojemu ciału, przywrócił mi duszę i pozwolił mi o Nim pamiętać.", "Po przebudzeniu.", "Wdzięczność za nowy poranek."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah jest moim Panem", "Allah, Allah jest moim Panem; Nie kojarzę z Nim niczego.", "W smutku i rozpaczy – Prorok ﷺ nauczył tego Asmę bint Umays (RA).", "Trzymaj się tawhid w chwilach niepokoju."),
        "dua_rahmataka_arju" to DuaText("Na Twoje Miłosierdzie liczę", "O Allahu, liczę na Twoje miłosierdzie. Nie zostawiaj mnie samego nawet na mgnienie oka i uporządkuj wszystkie moje sprawy. Nie ma boga oprócz Ciebie.", "Dua tego, który jest w niebezpieczeństwie (Da'awat al-makrub).", "Prorok ﷺ nazwał to dua tego, który jest w niebezpieczeństwie."),
        "dua_against_enemy_ahzab" to DuaText("Przeciwko armiom wroga", "O Allah, Objawicielu Księgi, Szybki w rachunku! Pokonaj konfederatów. O Allahu, pokonaj ich i potrząśnij nimi.", "Przeciw wrogowi — duet Bitwy Konfederatów.", "Dua Proroka ﷺ przeciwko wrogowi."),
        "dua_anta_adudi" to DuaText("Jesteś moim wsparciem", "O Allahu, jesteś moim wsparciem i pomocnikiem. Przez Ciebie planuję, przez Ciebie posuwam się naprzód i przez Ciebie walczę.", "Przed zawodami lub poważnym wyzwaniem.", "Prorok ﷺ powiedział to w bitwie."),
        "dua_ikfinihim" to DuaText("Wystarczy mi przeciwko nim", "O Allahu, wystarczy mi przeciwko nim, jakkolwiek zechcesz.", "Przeciw złu prześladowców – dua chłopca w opowieści o Ludze Rowu.", "Allah ocalił chłopca od prześladowców."),
        "dua_qadarullah" to DuaText("Kiedy dzieje się coś złego", "Takie jest postanowienie Allaha i On uczynił, co chciał.", "Kiedy dzieje się coś nieprzyjemnego, zamiast mówić „jeśli tylko”.", "„Gdyby tylko” otwiera drzwi do Szaytana."),
        "dua_ala_kulli_hal" to DuaText("Pochwała w każdej sytuacji", "Wszelka chwała jest dla Allaha w każdej sytuacji.", "Kiedy dzieje się coś, czego nie lubisz.", "Prorok ﷺ powiedział to w obliczu czegoś, czego nie lubił."),
        "dua_dogs_barking" to DuaText("Słychać szczekanie psów w nocy", "Szukam schronienia u Allaha przed Szaytanem, przeklętym.", "Gdy w nocy usłyszę szczekanie psów lub ryczenie osła.", "Widzą to, czego ty nie widzisz."),
        "dua_leaving_home_adilla" to DuaText("Schronienie przed zejściem na manowce", "O Allahu, szukam schronienia u Ciebie, abym nie zbłądził lub nie został sprowadzony na manowce, abym się nie poślizgnął lub nie został wprowadzony w błąd, abym nie zrobił nic złego lub nie został skrzywdzony, abym nie zachował się głupio lub nie został potraktowany głupio.", "Wychodząc z domu — opowiada Umm Salamah (RA).", "Prorok ﷺ recytował to za każdym razem, gdy opuszczał swój dom."),
        "dua_ascending_descending" to DuaText("Idąc w górę i schodząc w dół", "Allah jest Największy (kiedy idzie w górę). — Chwała Allahowi (kiedy schodzisz).", "Podczas podróży mów „Allahu Akbar” podczas wjazdu i „SubhanAllah” podczas schodzenia.", "Praktyka Towarzyszy (RA) podczas podróży."),
        "dua_traveller_sahar" to DuaText("Dua podróżnika przed świtem", "Słuchacz słyszał (i przekazał) naszą chwałę dla Allaha i Jego dobrodziejstw dla nas. Panie nasz, towarzysz nam i obdarz nas Swoją łaską – (mówię to) szukając schronienia u Allaha przed Ogniem.", "W podróży, przed świtem.", "Prorok ﷺ powiedział to przed świtem podczas podróży."),
        "dua_zawwadakallah" to DuaText("Do podróżnika: Niech Allah zapewni Taqła", "Niech Allah zapewni ci taqwę na twoją podróż, przebaczy ci grzechy i sprawi, że będzie ci dobrze, gdziekolwiek się znajdziesz.", "Żegnając podróżnika.", "Prorok ﷺ dał ten duet komuś wyruszającemu w podróż."),
        "dua_traveller_to_resident" to DuaText("Podróżnik do tych, którzy pozostają w tyle", "Powierzam was Allahowi, któremu nigdy nie ufamy.", "Wypowiedziane przez podróżnika podczas żegnania się z rodziną.", "Powierzenie bezpieczeństwa rodziny Allahowi."),
        "dua_entering_village" to DuaText("Wejście do miasta lub wsi", "O Allahu, Panie siedmiu niebios i wszystkiego, co zacieniają, Panie siedmiu ziem i wszystkiego, co niosą, Panie diabłów i wszystkich, których wprowadzają w błąd, Panie wiatrów i wszystkiego, co rozpraszają! Prosimy Cię o dobro tego miasta i jego mieszkańców i szukamy u Ciebie schronienia przed jego złem, złem jego mieszkańców i złem tego, co w nim jest.", "Przed wejściem do jakiegoś miasta.", "Prorok ﷺ recytował to za każdym razem, gdy chciał wejść do miasta."),
        "dua_vehicle_stumbles" to DuaText("Kiedy pojazd się potyka", "W imię Allaha.", "Kiedy wierzchowiec lub pojazd poślizgnie się lub potknie, zamiast mówić „Niech Szaytan zginie”.", "Wypowiedzenie Bismillah powoduje, że Szaytan kurczy się do rozmiarów muchy."),
        "dua_ajz_kasal_haram" to DuaText("Schronienie przed słabością i starością", "O Allahu, szukam u Ciebie schronienia przed bezradnością i lenistwem, przed tchórzostwem i starością, przed próbami życia i śmierci oraz przed karą grobową.", "Kompleksowy codzienny duet schronienia.", "Dua Proroka ﷺ często tworzona."),
    )
}
